module grid_symmetry_checker(input clk, input rst_n, input start, input [5:0] H_in, input [3:0] W_in, input [7:0] grid_flat [0:71], output reg result, output reg done); reg [5:0] H_reg; reg [3:0] W_reg; reg [7:0] grid_reg [0:71]; reg [5:0] perm [0:5]; reg [2:0] state; reg [11:0] col_mask; reg [3:0] current_col; reg [1:0] check_cols_state; reg success; reg [31:0] counter; always_ff @(posedge clk) if (!rst_n) begin H_reg <= 6'd0; W_reg <= 4'd0; grid_reg <= 72'd0; perm <= 6'd0; state <= 3'b000; col_mask <= 12'd0; current_col <= 4'd0; check_cols_state <= 2'b00; success <= 1'b0; done <= 1'b0; result <= 1'b0; end else begin case (state) 3'b000: if (start) begin H_reg <= H_in; W_reg <= W_in; grid_reg <= grid_flat; state <= 3'b001; end else begin state <= 3'b000; end 3'b001: case ({H_reg[2:0]}) 3'b000: perm <= 6'b000000; 3'b001: perm <= 6'b000010; 3'b010: perm <= 6'b000110; 3'b011: perm <= 6'b001110; 3'b100: perm <= 6'b010110; 3'b101: perm <= 6'b101110; default: perm <= 6'd0; endcase state <= 3'b011; 3'b011: if (check_cols_state == 0) begin current_col <= 0; col_mask <= 0; check_cols_state <= 1'b01; end if (counter > 50000) begin state <= 3'b100; end else begin counter <= counter + 1; end 3'b100: if (success) result <= 1'b1; done <= 1'b1; state <= 3'b100; default: state <= 3'b000; endcase end endmodule